-- =============================================================================
-- Catálogo — MUDELAR igual aos Excels, ONDA 1: alinhar os campos de negócio dos produtos que JÁ EXISTEM. MIGRATION DE DADOS.
-- Base de RH (uetjghdkwbywbftedtth).
-- =============================================================================
--
-- !!! SÓ PARA A BASE DE RH (uetjghdkwbywbftedtth). SÓ A MUDELAR (3242e925-da26-459a-8258-be04d904e355): todas as escritas
-- !!! levam o filtro da organização. Os ids e os valores «de» foram lidos na RH a 26/11/2026 (SELECT como administrador,
-- !!! sem RLS). Noutra base (a principal) a organização ou os produtos não existem com estes ids e a migration sai por
-- !!! RAISE NOTICE sem escrever nada. Antes do `db push`, confirmar supabase/.temp/project-ref = uetjghdkwbywbftedtth.
--
-- Pedido do dono: «men so faz que teja tudo como nos excels sf» (depois de «quero ... que eu tenha os produtos todos como
-- nos excels»). Fonte: os Excels da Mudelar (exportação de 20/11): Móveis WC = a Rev1 mais as linhas só do xlsx e do csv;
-- Revestimentos = a Rev1 mais as linhas só do csv; Torneiras = só a Rev1; Eletrodomésticos = o csv. Cruzamento e plano
-- gerados por script (mudelar-audit/onda1: o1_plan.py e o1_sql.py), fora da pasta do projeto.
--
-- O QUE FAZ, em 2843 produtos da Mudelar (lista fechada, embutida abaixo; nada se calcula na hora):
--   nome ..............   304  (tira « (sem preço)» e põe o nome do Excel; inclui as renomeações abaixo)
--   descrição .........  2543  (short_description, a que o Catálogo lê e grava; só onde a base está vazia)
--   marca .............    21  (brand_id de uma marca que JÁ existe; o gatilho acerta marca_livre)
--   fornecedor ........    76  (a ligação preferencial «Fornecedor Demo» passa ao fornecedor real do Excel, que já
--                              existe; o gatilho de item_suppliers acerta products.supplier_id; fornecedor_livre 76)
--   código fornecedor .   234  (item_suppliers.supplier_sku da ligação ao fornecedor do produto)
--   custo/PVP .........    84  (a linha ATUAL de product_prices: price e preco_exato, como cat_definir_pvp; a
--                              história fica em product_price_history pelo gatilho); preço da ligação 41
--   grossista/distr. ..    14  linhas novas (como cat_definir_grossista_distribuidor: valid_from depois do último preço)
--   Renomeações: 49 linhas do Excel sem produto que são o mesmo produto da base com outro nome (semelhança >= 0,8,
--   a mesma subcategoria e a mesma medida, nenhuma é «pai» com lista de cores) atualizam-se no PRÓPRIO produto.
--
-- O QUE NÃO FAZ: não muda SKU (nenhuma chamada a cat_gerar_sku_produto; C2 exige 0 SKU alterados), estado (onda 5),
-- subcategoria, modelo, atributos, unidade, stock, famílias, nem apaga nada. Não cria marcas, fornecedores, opções nem
-- produtos. Não mexe em orçamentos, negócios, compras nem receitas. IVA: 0 alterações (os 12 do Excel com 24 a 32 são
-- inválidos e ficam como estão; os que não têm linha de preço não têm onde o guardar). Onde o Excel está vazio, o valor
-- da base fica. EXCEÇÕES à letra do Excel (lista em mudelar-audit/onda1/fora.csv): «Resguardo Resguardo» e o código do
-- fabricante no nome continuam como o dono decidiu a 17/11; os pares «-2» continuam fora; os 145 consumíveis CONS-… não
-- entram (não estão no Excel de vendas).
--
-- GUARDAS (falham a migration inteira; nada fica): G0 a Mudelar existe (senão NOTICE e sai); G1 contagens de partida
-- (produtos vivos, famílias, membros); G2 cada produto existe, é da Mudelar, está vivo e tem o SKU esperado; G3 cada valor
-- «de» é o atual (ou todos já são «para»: já aplicada, sai por NOTICE); G4 marcas e fornecedores de destino vivos e da
-- Mudelar; G5 o utilizador da auditoria é membro ativo; G6 os eixos das famílias têm valores distintos.
-- Lock: pg_advisory_xact_lock(hashtextextended('cat_familias:' || org, 0)) e os produtos FOR NO KEY UPDATE por ordem.
-- CONFERÊNCIAS no fim: C1 contagens exatas; C2 0 SKU alterados na Mudelar; C3 impressão digital dos produtos (sem
-- updated_at; nos tocados, sem os campos desta onda); C4 preços e C5 ligações a fornecedores que não são desta onda iguais;
-- C6 atributos iguais; C7 famílias (548 / 14637, impressão digital e eixos distintos); C8 orçamentos, negócios, receitas,
-- compras e negocio_vista_cliente iguais; C9 nada escrito fora da Mudelar (xmin); C10 a cópia fechada (::text);
-- C11 cada valor «para» ficou gravado.
--
-- CÓPIA E REVERSÃO: o estado antigo de cada linha tocada fica no schema privado _mudelar_excel (onda1_*), só postgres.
-- REVERSÃO: fora da pasta das migrations (estar aqui é ser aplicada): mudelar-reverter-onda1.sql, guardado com o trabalho.
-- Repõe só o que ainda está com o valor desta onda. Para a aplicar, entra como uma migration nova.
--
-- ORDEM: depois de 20270129300000 (última no remoto RH a 26/11). `supabase db push` aplica TUDO o que estiver pendente:
-- listar com `supabase migration list --linked` imediatamente antes e empurrar só esta.
-- =============================================================================

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '5min';

